actions.action:
def created = []
def unchanged = []
def failed = []

def uri = "it/service_desk"
def tiket = "it/service_desk/sd_ticket"
def firma = "it/service_desk/sd_firma"
def tikety = "processIdentifier:\"" + tiket + "\""
def stav = { List kluce -> tikety + " AND dataSet.tk_stav.keyValue:(" + kluce.collect { "\"" + it + "\"" }.join(" OR ") + ")" }
def pre_zakaznika = ["zakaznik": tiket]
def pre_podporu = ["podpora": tiket]
def t = { String pole -> tiket + "-" + pole }

def views = [
        // "+" v tomto zobrazeni zalozi poziadavku a rovno ju otvori.
        // V zozname su len rozpisane - podane su v "Moje poziadavky".
        [id: "sd_podanie", name: i18n("Podanie požiadavky", ["en": "Submit a request"]),
         type: "Case", icon: "add_comment", query: stav(["rozpisana"]),
         nets: [tiket], roles: pre_zakaznika,
         headers: "meta-title," + t("tk_typ") + ",meta-creationDate"],
        // Svoje AJ firemne: viditelnost dava userRef `tk_firma_ludia`, takze
        // dopyt netreba zuzovat na cloveka. Stlpec "Podal" ich odlisi.
        [id: "sd_moje", name: i18n("Moje požiadavky", ["en": "My requests"]),
         type: "Case", icon: "inbox", query: stav(["nova", "v_rieseni", "caka", "vyriesena"]),
         nets: [tiket], roles: pre_zakaznika,
         headers: "meta-title," + t("tk_stav") + "," + t("tk_podal") + "," + t("tk_podane_o") + "," + t("tk_riesitel")],
        [id: "sd_na_prevzatie", name: i18n("Požiadavky na prevzatie", ["en": "Requests to pick up"]),
         type: "Case", icon: "move_to_inbox", query: stav(["nova"]),
         nets: [tiket], roles: pre_podporu,
         headers: "meta-title," + t("tk_firma_nazov") + "," + t("tk_priorita") + "," + t("sla_termin") + "," + t("tk_podal")],
        [id: "sd_v_rieseni", name: i18n("Požiadavky v riešení", ["en": "Requests in progress"]),
         type: "Case", icon: "pending_actions", query: stav(["v_rieseni", "caka"]),
         nets: [tiket], roles: pre_podporu,
         headers: "meta-title," + t("tk_stav") + "," + t("tk_firma_nazov") + "," + t("tk_riesitel") + "," + t("tk_priorita")],
        [id: "sd_vsetky", name: i18n("Všetky požiadavky podpory", ["en": "All support requests"]),
         type: "Case", icon: "confirmation_number", query: stav(["nova", "v_rieseni", "caka", "vyriesena"]),
         nets: [tiket], roles: pre_podporu,
         headers: "meta-title," + t("tk_stav") + "," + t("tk_firma_nazov") + "," + t("tk_podal") + "," + t("tk_podane_o")],
        [id: "sd_firmy", name: i18n("Firmy zákazníkov", ["en": "Customer companies"]),
         type: "Case", icon: "domain", query: "processIdentifier:\"" + firma + "\"",
         nets: [firma], roles: pre_podporu,
         headers: "meta-title," + firma + "-f_kod," + firma + "-f_aktivna," + firma + "-f_pocet"],
]

// Polozky predoslej verzie Service Desku (verejny formular, pracovne ulohy,
// register zakaznikov). Vyhodenie z tejto siete ich NEZMAZE - polozky su
// pripady `preference_filter_item` a v bezacej instancii by zostali navzdy.
def zastarane = ["sd_tickets", "sd_my_work", "sd_customers", "sd_submissions", "sd_new_request"]
def zmazane = []
zastarane.each { id ->
    try {
        def stara = menu_item(id)
        if (stara == null) return
        def filter = getFilterFromMenuItem(stara)
        deleteMenuItem(stara)
        if (filter != null) deleteFilter(filter)
        zmazane << id
    } catch (Exception e) {
        failed << (id + " (delete: " + e.getClass().simpleName + ": " + e.message + ")")
    }
}

views.each { v ->
    def id = v.id as String
    try {
        def existing = menu_item(id)
        if (existing != null) {
            def current = getFilterFromMenuItem(existing)
            def currentQuery = ((current?.dataSet?."filter"?.value ?: "") as String)
            def currentNets = ((current?.dataSet?."filter"?.allowedNets ?: []) as List)
                    .collect { it as String } as Set
            def wantNets = (v.nets as List).collect { it as String } as Set
            def currentName = current?.dataSet?."i18n_filter_name"?.value
            def sameName = currentName != null &&
                    (currentName.defaultValue as String) == (v.name.defaultValue as String) &&
                    (currentName.translations ?: [:]) == (v.name.translations ?: [:])
            // Aj ROLY: inak by uz nasadena polozka zostala viditelna vsetkym.
            def currentRoles = [] as Set
            (existing.immediateData ?: []).each { d ->
                if (d.importId == "allowed_roles") {
                    currentRoles = ((d.options ?: [:]).keySet() as Set)
                }
            }
            def wantRoles = (v.roles ?: [:]).collect { r, n -> (r as String) + ":" + (n as String) } as Set
            if (currentQuery == (v.query as String) && currentNets == wantNets && sameName
                    && currentRoles == wantRoles) {
                nastav_zobrazenie(existing, v.nets as List, v.headers)
                pripoj_do_uzla(existing, uri)
                unchanged << id
                return
            }
            deleteMenuItem(existing)
            if (current != null) {
                deleteFilter(current)
            }
        }
        def item = createOrUpdateMenuItem(
                id,                 // menu_item_identifier
                uri,                // URI cesta - musi sedet s uriNodes
                v.type as String,
                v.query as String,
                v.icon as String,
                v.name,             // I18nString
                v.nets as List,     // allowedNets - bez toho ziadne stlpce ani "+"
                v.roles as Map,     // allowed_roles: kto polozku v menu vidi
                [:]                 // bannedRoles - dourcuje aritu na projektovu
        )
        if (item) { created << id } else { failed << id }
        nastav_zobrazenie(item, v.nets as List, v.headers)
    } catch (Exception e) {
        failed << (id + " (" + e.getClass().simpleName + ": " + e.message + ")")
    }
}

// Zosuladenie roly `zakaznik` - viz komentar v hlavicke.
int roly = 0
try {
    findCases { it.processIdentifier.eq(firma) }.each { f ->
        userIdsOf(f.dataSet["f_clenovia"]?.value).each { uid ->
            if (setProcessRole(uid as String, "zakaznik", tiket, "", true)) roly++
        }
    }
} catch (Exception e) {
    failed << ("customer roles (" + e.getClass().simpleName + ": " + e.message + ")")
}

// Vysledok do nazvu casu: po createFilterInMenu sa zapis do vlastneho casu
// neuchova, changeCaseProperty prezije.
def summary = "Menu Service Desku – " + (created.size() + unchanged.size()) + "/" + views.size() +
        ", roly zákazníkov: " + roly + (zmazane ? (", zmazané staré: " + zmazane.size()) : "")
if (failed) {
    summary = "CHYBA menu Service Desku – nepodarilo sa: " + failed.join(", ")
}
changeCaseProperty("title").about { summary }

document.function:
{ def menuItem, def nets, def headers ->
    // `enable_case_title`  - vypnuty dialog "Vyplnte nazov pripadu" pri "+";
    //                        nazov si sklada siet sama.
    // `default_headers`    - predvolene stlpce zoznamu.
    // Ani jedno nie je argument `createOrUpdateMenuItem`.
    if (menuItem == null) return
    def payload = [:]
    if (nets) {
        payload.put("enable_case_title", ["value": false, "type": "boolean"])
        payload.put("case_require_title_in_creation", ["value": false, "type": "boolean"])
    }
    if (headers) {
        payload.put("default_headers", ["value": headers as String, "type": "text"])
    }
    if (payload) {
        setData("view", menuItem, payload)
    }
}

{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by sa pri kazdom spusteni zalozila druha sada.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}
